import json

_counter = {"id": "1", "value": 0}

_ROUTES = {
    "/counter": "GET",
    "/counter/increment": "POST",
    "/counter/reset": "POST",
}


def _snapshot():
    return {"id": _counter["id"], "value": _counter["value"]}


def handle(method, path, body):
    if path != "/" and path.endswith("/"):
        path = path.rstrip("/")
    if path not in _ROUTES:
        return 404, {"error": "找不到此路徑"}
    if method != _ROUTES[path]:
        return 405, {"error": "不允許此請求方法"}

    if path == "/counter":
        return 200, _snapshot()
    if path == "/counter/increment":
        _counter["value"] += 1
        return 200, _snapshot()
    if path == "/counter/reset":
        _counter["value"] = 0
        return 200, _snapshot()
    return 404, {"error": "找不到此路徑"}

