(function () {
  var countEl = document.getElementById('count');
  var errorEl = document.getElementById('error');
  var incBtn = document.getElementById('increment-btn');
  var resetBtn = document.getElementById('reset-btn');

  function showError(message) {
    errorEl.textContent = message;
    errorEl.hidden = false;
  }

  function clearError() {
    errorEl.textContent = '';
    errorEl.hidden = true;
  }

  function setBusy(busy) {
    incBtn.disabled = busy;
    resetBtn.disabled = busy;
  }

  async function handleResponse(res) {
    var data = null;
    try {
      data = await res.json();
    } catch (e) {
      data = null;
    }
    if (!res.ok) {
      var msg = data && data.error ? data.error : '請求失敗（狀態碼 ' + res.status + '）';
      throw new Error(msg);
    }
    if (!data || typeof data.value === 'undefined') {
      throw new Error('伺服器回應格式不正確。');
    }
    return data;
  }

  function networkError() {
    return new Error('無法連線到伺服器，請稍後再試。');
  }

  async function getCounter() {
    var res;
    try {
      res = await fetch('api/counter', { method: 'GET' });
    } catch (e) {
      throw networkError();
    }
    return handleResponse(res);
  }

  async function incrementCounter() {
    var res;
    try {
      res = await fetch('api/counter/increment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      });
    } catch (e) {
      throw networkError();
    }
    return handleResponse(res);
  }

  async function resetCounter() {
    var res;
    try {
      res = await fetch('api/counter/reset', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      });
    } catch (e) {
      throw networkError();
    }
    return handleResponse(res);
  }

  async function run(action) {
    setBusy(true);
    try {
      var data = await action();
      countEl.textContent = String(data.value);
      clearError();
    } catch (e) {
      showError('錯誤：' + e.message);
    } finally {
      setBusy(false);
    }
  }

  incBtn.addEventListener('click', function () {
    run(incrementCounter);
  });

  resetBtn.addEventListener('click', function () {
    run(resetCounter);
  });

  run(getCounter);
})();

